    createCanvas(windowWidth, windowHeight)
    fft = new p5.FFT()
}

function draw() {
    backgorund(0)
}

function mouseClicked() {
    if (ambience.isPlaying()) {
        ambience.pause()
    } else {
        ambience.play()
    }
}
